#!/usr/bin/env python3
"""
Instalador del MCP de control EN VIVO de Microsoft Project.

Ejecutalo dentro de la carpeta del repo MCP-Ms-Project clonado:
    python setup_msproject_live.py

Crea la carpeta ms-project-live/ con todos los archivos del servidor MCP,
el plugin VBA y los tests. Luego haz commit y push (GitHub Desktop o git).
"""
import base64, os

BASE = "ms-project-live"

FILES = {
    'README.md': "",
    'adapters/__init__.py': "",
    'adapters/base.py': "",
    'adapters/com_adapter.py': "",
    'adapters/fake_adapter.py': "",
    'claude_desktop_config.ejemplo.json': "",
    'config.py': "",
    'requirements.txt': "",
    'server.py': "",
    'service.py': "",
    'tests/__init__.py': "",
    'tests/test_service.py': "",
    'vba/ClaudeMSProject.bas': "",
}

def main():
    for rel, b64 in FILES.items():
        dest = os.path.join(BASE, rel)
        os.makedirs(os.path.dirname(dest), exist_ok=True)
        with open(dest, "wb") as fh:
            fh.write(base64.b64decode(b64))
        print("  creado:", dest)
    print()
    print("OK - 13 archivos creados en la carpeta ms-project-live/")
    print("Ahora en GitHub Desktop: Summary -> Commit to main -> Push.")

if __name__ == "__main__":
    main()
